package cli

import (
	"fmt"
	"sort"
	"time"

	"github.com/mvanhorn/printing-press-library/library/commerce/flipkart/internal/store"

	"github.com/spf13/cobra"
)

func newOffersBestCardCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:         "best-card <url1> <url2> [url3...]",
		Short:       "Find the single bank card that maximizes total stacked savings across a set of products.",
		Long:        "Resolves fresh bank/card offers for each given product URL, then aggregates total savings per card/description across just this set — useful when deciding which of your cards to use across a multi-item cart.",
		Example:     `  flipkart-pp-cli offers best-card "https://www.flipkart.com/oppo-a3x-8-gb-ram-128-gb-storage-lake-green/p/itmc050065f36601?pid=MOBH4ZCFEQZFQBFB" "https://www.flipkart.com/samsung-galaxy-m06-5g-mint-green-128-gb/p/itmc0501a8c1f5e5?pid=MOBH8QSVDVBRZFNJ"`,
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			if len(args) < 2 {
				return usageErr(fmt.Errorf("offers best-card requires at least 2 product URLs, got %d\nUsage: %s <url1> <url2> [url3...]", len(args), cmd.CommandPath()))
			}

			if dryRunOK(flags) {
				fmt.Fprintln(cmd.ErrOrStderr(), "would fetch fresh offers for:")
				for _, u := range args {
					fmt.Fprintf(cmd.ErrOrStderr(), "  %s\n", u)
				}
				fmt.Fprintln(cmd.ErrOrStderr(), "(dry run - no request sent)")
				return nil
			}

			c, err := flags.newClient()
			if err != nil {
				return err
			}

			db, err := store.OpenWithContext(cmd.Context(), defaultDBPath("flipkart-pp-cli"))
			if err != nil {
				return fmt.Errorf("opening local database: %w", err)
			}
			defer db.Close()
			if err := db.EnsureFlipkartSchema(); err != nil {
				return err
			}

			now := time.Now()
			productIDs := make([]string, 0, len(args))
			perProductResults := make([]*flipkartOffersResult, 0, len(args))
			for _, u := range args {
				result, err := fetchProductOffers(cmd.Context(), c.HTTPClient, u)
				if err != nil {
					return classifyFetchErr(fmt.Errorf("fetching offers for %s: %w", u, err))
				}
				if err := db.UpsertFlipkartProductMRP(result.ProductID, result.URL, result.MRP, result.DiscountPct); err != nil {
					return fmt.Errorf("storing MRP/discount for %s: %w", result.ProductID, err)
				}
				storeOffers := make([]store.FlipkartOffer, 0, len(result.BankOffers))
				for _, o := range result.BankOffers {
					storeOffers = append(storeOffers, store.FlipkartOffer{AmountOff: o.AmountOff, Description: o.Description})
				}
				if err := db.ReplaceFlipkartOffers(result.ProductID, storeOffers, now); err != nil {
					return fmt.Errorf("storing offers for %s: %w", result.ProductID, err)
				}
				productIDs = append(productIDs, result.ProductID)
				perProductResults = append(perProductResults, result)
			}

			rows, err := db.FlipkartOffersForProducts(productIDs)
			if err != nil {
				return fmt.Errorf("reading stored offers: %w", err)
			}
			if len(rows) == 0 {
				return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
					"status":   "no_offers_found",
					"message":  "no bank offers were found for any of the given products — cannot recommend a best card",
					"products": perProductResults,
				}, flags)
			}

			type cardTotal struct {
				Description string             `json:"description"`
				Total       float64            `json:"total"`
				PerProduct  map[string]float64 `json:"per_product"`
			}
			totals := map[string]*cardTotal{}
			for _, r := range rows {
				ct, ok := totals[r.Description]
				if !ok {
					ct = &cardTotal{Description: r.Description, PerProduct: map[string]float64{}}
					totals[r.Description] = ct
				}
				ct.Total += r.AmountOff
				ct.PerProduct[r.ProductID] += r.AmountOff
			}

			breakdown := make([]*cardTotal, 0, len(totals))
			for _, ct := range totals {
				breakdown = append(breakdown, ct)
			}
			sort.Slice(breakdown, func(i, j int) bool { return breakdown[i].Total > breakdown[j].Total })

			best := breakdown[0]
			return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
				"status": "ok",
				"best_card": map[string]any{
					"description": best.Description,
					"total":       best.Total,
				},
				"breakdown": breakdown,
				"products":  perProductResults,
			}, flags)
		},
	}
	return cmd
}
